package com.gsterling.press; import android.content.*;import androidx.work.*;import java.util.*;import java.util.concurrent.TimeUnit; final class Scheduler{enum Mode{OFF,DAILY,TEST}static final String NAME="black-tide-rotation";static void schedule(Context c,Mode m){WorkManager w=WorkManager.getInstance(c);if(m==Mode.OFF){w.cancelUniqueWork(NAME);return;}long delay;if(m==Mode.TEST)delay=5*60*1000L;else{Calendar now=Calendar.getInstance(),n=(Calendar)now.clone();n.set(Calendar.HOUR_OF_DAY,4);n.set(Calendar.MINUTE,0);n.set(Calendar.SECOND,0);n.set(Calendar.MILLISECOND,0);if(!n.after(now))n.add(Calendar.DAY_OF_YEAR,1);delay=n.getTimeInMillis()-now.getTimeInMillis();}OneTimeWorkRequest r=new OneTimeWorkRequest.Builder(RotationWorker.class).setInitialDelay(delay,TimeUnit.MILLISECONDS).build();w.enqueueUniqueWork(NAME,ExistingWorkPolicy.REPLACE,r);}}